def my_import(name, path=None):
    """Return imported module for the given name."""
    import sys
    import importlib

    if path is None:
        path = name
    if path in sys.modules:
        return sys.modules[path]

    try:
        return importlib.import_module(path)
    except ImportError:
        return None

