def get_module_name(name):
    """Return name of the module for the given name."""
    if name.endswith('.'):
        name = name[:-1]
    name = name.replace('/', '.')
    return name


def is_module_available(name):
    """Check if the module is available."""
    if name.endswith('.'):
        name = name[:-1]
    name = name.replace('/', '.')
    module = importlib.import_module(name)
    return module is not None


